open('/task/workspace/invoice/core.py','w').write('''from decimal import Decimal, ROUND_HALF_UP\n\nQ = Decimal("0.01")\n\ndef _r(x):\n    return x.quantize(Q, rounding=ROUND_HALF_UP)\n\nTIER = {"gold": Decimal("0.05"), "silver": Decimal("0.02")}\n\ndef compute_invoice(lines, customer):\n    sub = Decimal("0")\n    for l in lines:\n        amt = Decimal(l["qty"]) * Decimal(str(l["unit_price"]))\n        if l["qty"] >= 100:\n            amt *= Decimal("0.90")\n        sub += _r(amt)\n    disc = _r(sub * TIER.get(customer.get("tier"), Decimal("0")))\n    rate = Decimal("0")\n    tax = _r((sub - disc) * rate)\n    total = sub - disc + tax\n    return {"subtotal": str(_r(sub)), "discount": str(disc), "tax": str(tax), "total": str(_r(total))}\n\n\ndef format_money(amount, currency):\n    raise NotImplementedError\n''')
